import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  BackHandler,
  type DimensionValue,
  type GestureResponderEvent,
  type LayoutChangeEvent,
  type LayoutRectangle,
  Pressable,
  useWindowDimensions,
  type View,
  type ViewStyle,
} from "react-native";
import Animated, {
  Easing,
  Extrapolation,
  interpolate,
  type SharedValue,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { useRelativePosition } from "@/hooks/use-relative-position";
import { cn, mergeRefs } from "@/lib/utils";
import { Portal, PortalWindow } from "@/components/ui/portal";
import { Scrim, type ScrimProps } from "@/components/ui/scrim";
import { Slot } from "@/components/ui/slot";

// Constants
const ANIMATION_DURATION = 200;
const ANIMATION_EASING = Easing.out(Easing.cubic);
const SCREEN_MARGIN = 12;
const FIT_MAX_WIDTH = 280;

// Types
type LayoutPosition = {
  pageX: number;
  pageY: number;
  width: number;
  height: number;
};

type PopoverSide = "top" | "bottom" | "left" | "right";
type PopoverAlign = "start" | "center" | "end";

type PopoverContextProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  visibilityProgress: SharedValue<number>;
  triggerPosition?: LayoutPosition;
  setTriggerPosition: (position?: LayoutPosition) => void;
  contentLayout?: LayoutRectangle;
  setContentLayout: (position?: LayoutRectangle) => void;
};

type PopoverProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: React.ReactNode;
};

type PopoverPortalProps = Partial<React.ComponentProps<typeof Portal>>;

type PopoverScrimProps = Omit<ScrimProps, "open" | "visibilityProgress">;

type PopoverContentProps = React.ComponentProps<typeof View> & {
  avoidCollisions?: boolean;
  side?: PopoverSide;
  sideOffset?: number;
  align?: PopoverAlign;
  alignOffset?: number;
  width?: "full" | "fit" | "auto" | "trigger" | number | `${number}%`;
};

type PopoverTriggerProps = React.ComponentPropsWithRef<typeof Pressable> & {
  asChild?: boolean;
};

type PopoverCloseProps = React.ComponentPropsWithRef<typeof Pressable> & {
  asChild?: boolean;
};

// Context
const PopoverContext = createContext<PopoverContextProps | null>(null);

export const usePopover = () => {
  const context = useContext(PopoverContext);
  if (!context) {
    throw new Error("usePopover must be used within a Popover");
  }
  return context;
};

// Components
export const Popover = ({
  open: openProp,
  onOpenChange: onOpenChangeProp,
  children,
}: PopoverProps) => {
  const [internalOpen, setInternalOpen] = useState(openProp ?? false);
  const [contentLayout, setContentLayout] = useState<LayoutRectangle>();
  const [triggerPosition, setTriggerPosition] = useState<LayoutPosition>();

  const isControlled = openProp !== undefined;
  const open = isControlled ? openProp : internalOpen;

  const visibilityProgress = useSharedValue(open ? 1 : 0);

  const onOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (!isControlled) {
        setInternalOpen(nextOpen);
      }
      onOpenChangeProp?.(nextOpen);
    },
    [isControlled, onOpenChangeProp]
  );

  useEffect(() => {
    visibilityProgress.value = withTiming(open ? 1 : 0, {
      duration: ANIMATION_DURATION,
      easing: ANIMATION_EASING,
    });
  }, [open, visibilityProgress]);

  useEffect(() => {
    if (!open) {
      return;
    }

    const subscription = BackHandler.addEventListener(
      "hardwareBackPress",
      () => {
        onOpenChange(false);
        return true;
      }
    );

    return () => {
      subscription.remove();
    };
  }, [open, onOpenChange]);

  const ctx = useMemo(
    () => ({
      contentLayout,
      onOpenChange,
      open,
      setContentLayout,
      setTriggerPosition,
      triggerPosition,
      visibilityProgress,
    }),
    [open, triggerPosition, contentLayout, visibilityProgress, onOpenChange]
  );

  return (
    <PopoverContext.Provider value={ctx}>{children}</PopoverContext.Provider>
  );
};

export const PopoverTrigger = ({
  asChild,
  ref: refProp,
  onPress: onPressProp,
  ...props
}: PopoverTriggerProps) => {
  const { open, onOpenChange, setTriggerPosition } = usePopover();
  const ref = useRef<React.ComponentRef<typeof Pressable>>(null);

  const mergedRefs = mergeRefs(ref, refProp);

  const handlePress = useCallback(
    (e: GestureResponderEvent) => {
      onPressProp?.(e);

      if (open) {
        onOpenChange(false);
        return;
      }

      ref.current?.measure((_x, _y, width, height, pageX, pageY) => {
        setTriggerPosition({
          height,
          pageX,
          pageY,
          width,
        });

        onOpenChange(true);
      });
    },
    [open, onOpenChange, onPressProp, setTriggerPosition]
  );

  const Comp = asChild ? Slot.Pressable : Pressable;

  return (
    <Comp
      {...props}
      collapsable={false}
      onPress={handlePress}
      ref={mergedRefs}
    />
  );
};

export const PopoverClose = ({
  asChild,
  onPress,
  ...props
}: PopoverCloseProps) => {
  const { onOpenChange } = usePopover();

  const Comp = asChild ? Slot.Pressable : Pressable;

  return (
    <Comp
      {...props}
      onPress={(event) => {
        onPress?.(event);
        onOpenChange(false);
      }}
    />
  );
};

export const PopoverPortal = ({
  children,
  name,
  ...portalProps
}: PopoverPortalProps) => {
  const id = useId();
  const ctx = usePopover();
  const [mounted, setMounted] = useState(ctx.open);

  useEffect(() => {
    if (ctx.open) {
      setMounted(true);
      return;
    }

    const timeout = setTimeout(() => {
      setMounted(false);
    }, ANIMATION_DURATION);

    return () => {
      clearTimeout(timeout);
    };
  }, [ctx.open]);

  if (!mounted) {
    return null;
  }

  return (
    <Portal name={name ?? `popover-${id}`} {...portalProps}>
      <PopoverContext.Provider value={ctx}>
        <PortalWindow>{children}</PortalWindow>
      </PopoverContext.Provider>
    </Portal>
  );
};

export const PopoverScrim = ({
  closeOnPress = true,
  onPress,
  ...props
}: PopoverScrimProps) => {
  const { onOpenChange, open, visibilityProgress } = usePopover();

  return (
    <Scrim
      {...props}
      closeOnPress={closeOnPress}
      onPress={(event) => {
        onPress?.(event);
        if (closeOnPress) {
          onOpenChange(false);
        }
      }}
      open={open}
      visibilityProgress={visibilityProgress}
    />
  );
};

export const PopoverContent = ({
  children,
  className,
  onLayout: onLayoutProp,
  style,
  width = "fit",
  avoidCollisions = true,
  side = "bottom",
  sideOffset = 8,
  align = "center",
  alignOffset = 0,
  ...props
}: PopoverContentProps) => {
  const {
    visibilityProgress,
    triggerPosition,
    setContentLayout,
    contentLayout,
  } = usePopover();
  const insets = useSafeAreaInsets();
  const dimensions = useWindowDimensions();

  const positionInsets = useMemo(
    () => ({
      bottom: insets.bottom + SCREEN_MARGIN,
      left: insets.left + SCREEN_MARGIN,
      right: insets.right + SCREEN_MARGIN,
      top: insets.top + SCREEN_MARGIN,
    }),
    [insets]
  );

  const onLayout = useCallback(
    (event: LayoutChangeEvent) => {
      setContentLayout(event.nativeEvent.layout);
      onLayoutProp?.(event);
    },
    [setContentLayout, onLayoutProp]
  );

  const transformOrigin = getContentTransformOrigin(side, align);
  const translateXSign = getTranslateSign(side, "x");
  const translateYSign = getTranslateSign(side, "y");

  const animatedStyle = useAnimatedStyle(() => {
    const progress = visibilityProgress.value;
    const opacity = interpolate(progress, [0, 1], [0, 1], Extrapolation.CLAMP);
    const scale = interpolate(progress, [0, 1], [0.92, 1], Extrapolation.CLAMP);
    const offset = interpolate(progress, [0, 1], [6, 0], Extrapolation.CLAMP);

    return {
      opacity,
      transform: [
        { translateX: offset * translateXSign },
        { translateY: offset * translateYSign },
        { scale },
      ],
      transformOrigin,
    };
  });

  const positionStyle = useRelativePosition({
    align,
    alignOffset,
    avoidCollisions,
    contentLayout: contentLayout ?? null,
    insets: positionInsets,
    side,
    sideOffset,
    triggerPosition: triggerPosition ?? null,
  });

  const widthStyle = getContentWidthStyle(
    width,
    triggerPosition?.width,
    Math.min(
      FIT_MAX_WIDTH,
      dimensions.width - positionInsets.left - positionInsets.right
    )
  );

  if (!triggerPosition) {
    return null;
  }

  return (
    <Animated.View
      {...props}
      className={cn(
        "border-border bg-popover z-50 rounded-xl border p-3 shadow-lg",
        className
      )}
      collapsable={false}
      onLayout={onLayout}
      pointerEvents={contentLayout ? "auto" : "none"}
      style={[
        positionStyle,
        widthStyle,
        animatedStyle,
        contentLayout ? null : { opacity: 0 },
        style,
      ]}
    >
      {children}
    </Animated.View>
  );
};

// Utils
function getContentWidthStyle(
  width: NonNullable<PopoverContentProps["width"]>,
  triggerWidth: number | undefined,
  maxFitWidth: number
): ViewStyle {
  if (width === "full") {
    return { width: "100%" };
  }

  if (width === "trigger") {
    return { width: triggerWidth };
  }

  if (width === "auto") {
    return { width: "auto" };
  }

  if (typeof width === "number") {
    return { width };
  }

  if (width.endsWith("%")) {
    return { width: width as DimensionValue };
  }

  return {
    alignSelf: "flex-start",
    maxWidth: maxFitWidth,
  };
}

function getContentTransformOrigin(side: PopoverSide, align: PopoverAlign) {
  let x = "center";
  if (side === "left") {
    x = "right";
  } else if (side === "right") {
    x = "left";
  } else if (align === "start") {
    x = "left";
  } else if (align === "end") {
    x = "right";
  }

  let y = "center";
  if (side === "top") {
    y = "bottom";
  } else if (side === "bottom") {
    y = "top";
  } else if (align === "start") {
    y = "top";
  } else if (align === "end") {
    y = "bottom";
  }

  return `${x} ${y}`;
}

function getTranslateSign(side: PopoverSide, axis: "x" | "y") {
  if (axis === "x") {
    if (side === "left") {
      return 1;
    }
    if (side === "right") {
      return -1;
    }
    return 0;
  }

  if (side === "top") {
    return 1;
  }
  if (side === "bottom") {
    return -1;
  }
  return 0;
}

import { useMemo } from "react";
import { useWindowDimensions } from "react-native";
import {
  getRelativePosition,
  type UseRelativePositionArgs,
} from "@/lib/relative-position";

export function useRelativePosition(args: UseRelativePositionArgs) {
  const { width, height } = useWindowDimensions();
  const {
    align,
    alignOffset,
    avoidCollisions,
    contentLayout,
    insets,
    side,
    sideOffset,
    triggerPosition,
  } = args;
  return useMemo(
    () =>
      getRelativePosition({
        align,
        alignOffset,
        avoidCollisions,
        contentLayout,
        dimensions: { height, width },
        insets,
        side,
        sideOffset,
        triggerPosition,
      }),
    [
      align,
      alignOffset,
      avoidCollisions,
      contentLayout,
      insets,
      side,
      sideOffset,
      triggerPosition,
      width,
      height,
    ]
  );
}

import type { LayoutRectangle } from "react-native";
import type { EdgeInsets } from "react-native-safe-area-context";

type LayoutPosition = {
  pageX: number;
  pageY: number;
  width: number;
  height: number;
};

export type UseRelativePositionArgs = {
  align?: "start" | "center" | "end";
  avoidCollisions?: boolean;
  contentLayout: LayoutRectangle | null;
  alignOffset?: number;
  insets?: EdgeInsets;
  side?: "top" | "bottom" | "left" | "right";
  sideOffset?: number;
  triggerPosition: LayoutPosition | null;
};

type PositionStyle = {
  position: "absolute";
  top: number;
  left: number;
  maxWidth?: number;
  maxHeight?: number;
  opacity?: number;
};

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(value, max));

const alignPosition = (
  start: number,
  triggerSize: number,
  contentSize: number,
  align: NonNullable<UseRelativePositionArgs["align"]>,
  offset: number
) => {
  const fraction = align === "start" ? 0 : align === "end" ? 1 : 0.5;
  return start + (triggerSize - contentSize) * fraction + offset;
};

/** Calculate once from measurements; the hook only supplies window dimensions. */
export function getRelativePosition({
  align = "start",
  avoidCollisions = true,
  triggerPosition: trigger,
  contentLayout: content,
  alignOffset = 0,
  insets,
  side = "bottom",
  sideOffset = 0,
  dimensions,
}: UseRelativePositionArgs & {
  dimensions: { width: number; height: number };
}): PositionStyle {
  if (!trigger) {
    return { left: -9999, opacity: 0, position: "absolute", top: -9999 };
  }
  if (!content) {
    return {
      left: trigger.pageX,
      opacity: 0,
      position: "absolute",
      top: trigger.pageY,
    };
  }

  const insetLeft = insets?.left ?? 0;
  const insetRight = insets?.right ?? 0;
  const insetTop = insets?.top ?? 0;
  const insetBottom = insets?.bottom ?? 0;
  const maxWidth = Math.max(0, dimensions.width - insetLeft - insetRight);
  const maxHeight = Math.max(0, dimensions.height - insetTop - insetBottom);
  const width = avoidCollisions
    ? Math.min(content.width, maxWidth)
    : content.width;
  const height = avoidCollisions
    ? Math.min(content.height, maxHeight)
    : content.height;

  let left: number;
  let top: number;
  if (side === "top" || side === "bottom") {
    left = alignPosition(
      trigger.pageX,
      trigger.width,
      width,
      align,
      alignOffset
    );
    top =
      side === "top"
        ? trigger.pageY - sideOffset - height
        : trigger.pageY + trigger.height + sideOffset;
  } else {
    top = alignPosition(
      trigger.pageY,
      trigger.height,
      height,
      align,
      alignOffset
    );
    left =
      side === "left"
        ? trigger.pageX - sideOffset - width
        : trigger.pageX + trigger.width + sideOffset;
  }

  if (!avoidCollisions) {
    return { left, position: "absolute", top };
  }

  return {
    left: clamp(left, insetLeft, dimensions.width - insetRight - width),
    maxHeight,
    maxWidth,
    position: "absolute",
    top: clamp(top, insetTop, dimensions.height - insetBottom - height),
  };
}
